slides.code:
.box {
  background: blue;
}

/* ekran 768px yoki kichik */
@media (max-width: 768px) {
  .box {
    background: red;
  }
}

/* mobile-first: avval telefon */
.box { font-size: 16px; }

/* 768px va undan katta ekranlar uchun qo'shamiz */
@media (min-width: 768px) {
  .box { font-size: 24px; }
}

.menu {
  display: flex;
  flex-direction: row;       /* kompyuter */
  gap: 20px;
}
@media (max-width: 768px) {
  .menu {
    flex-direction: column;  /* telefon */
  }
}

.gallery {
  display: grid;
  grid-template-columns: repeat(3, 1fr);  /* kompyuter */
  gap: 20px;
}
@media (max-width: 1024px) {
  .gallery { grid-template-columns: repeat(2, 1fr); }  /* planshet */
}
@media (max-width: 600px) {
  .gallery { grid-template-columns: 1fr; }  /* telefon */
}

